interfaces.interface:
ALTER TABLE landing_pages ADD COLUMN particles BOOLEAN DEFAULT false;
ALTER TABLE landing_pages ADD COLUMN particle_style TEXT DEFAULT 'dots';
-- Values: 'dots' | 'stars' | 'sparkles' | 'bokeh'
ALTER TABLE landing_pages ADD COLUMN particle_density TEXT DEFAULT 'normal';
-- Values: 'sparse' | 'normal' | 'dense'
ALTER TABLE landing_pages ADD COLUMN particle_color TEXT;

@keyframes float {
  0%, 100% { transform: translateY(100vh); opacity: 0; }
  10% { opacity: 1; }
  90% { opacity: 1; }
  100% { transform: translateY(-100vh); opacity: 0; }
}
.particle { position: absolute; animation: float linear infinite; }
.particle-dots { width: 6px; height: 6px; border-radius: 50%; }
.particle-bokeh { width: 20px; height: 20px; filter: blur(4px); }
